/* Igreja Master 3.7.29 — REDESIGN DAS TELAS REAIS, não um splash de APK.
   Carregado APÓS as folhas de 3.7.27; dá o mesmo padrão à web e ao WebView.
   Usa somente variáveis --church-primary / secondary da igreja autenticada. */
:root{
 --im-ink:#102e57; --im-muted:#5e7593; --im-line:#d7e5f5;
 --im-bg:#f4f8ff; --im-card:#fff; --im-primary:var(--church-primary,#0d47a1);
 --im-soft:#e9f3ff; --im-shadow:0 7px 24px rgba(15,53,100,.075);
 color-scheme:light;
}
html{scroll-behavior:smooth}
body{background:var(--im-bg)!important;color:var(--im-ink);font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif;}
a{color:var(--im-primary)}
a:hover{text-decoration-color:var(--church-secondary,#1976d2)}
input,textarea,select,button{font:inherit}
[hidden]{display:none!important}
:focus-visible{outline:3px solid #62a9ed!important;outline-offset:2px}
.content{color:var(--im-ink)}
.content h1,.content h2,.content h3{color:#123764}
.content .card,.content .stat,.dashboard-action,.content .form-card,.content .module-card{
 background:#fff!important;border:1px solid var(--im-line)!important;
 border-radius:16px!important;box-shadow:var(--im-shadow)!important;
}
.content .card-pad{padding:clamp(16px,2vw,24px)}
.content .muted,.content .help-text,.content small{color:var(--im-muted)}
.content .eyebrow{color:var(--im-primary);letter-spacing:.075em}
.app-topbar{
 background:#fff!important;border-bottom:1px solid #dfebf8!important;
 box-shadow:0 2px 12px rgba(20,59,110,.045)!important;
}
.breadcrumb strong{color:var(--im-ink)!important;font-size:16px}
.breadcrumb>span{color:var(--im-muted)!important}
.module-title h1,.content>.page-head h1{font-size:clamp(21px,2vw,27px)!important;color:#103764!important}
.content .btn,.app-dialog .btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;
 font-size:13px;font-weight:700;letter-spacing:0;min-height:44px;border-radius:10px}
.content .btn-primary,.app-dialog .btn-primary,.btn.primary{
 background:var(--im-primary)!important;color:#fff!important;border:1px solid transparent!important
}
.content .btn-primary:hover,.app-dialog .btn-primary:hover{filter:brightness(.92)}
.content .btn-light,.app-dialog .btn-light{
 background:#f8fbff!important;color:#124775!important;border:1px solid #c3d8ef!important
}
.content .btn-light:hover,.app-dialog .btn-light:hover{background:#e9f3ff!important}
.content .field,.content .form-grid>label{min-width:0}
.content .field>label,.content .form-grid>label,.content .form-grid label,
.app-dialog .field>label,.app-dialog .form-grid>label{
 font-size:12px!important;font-weight:700!important;color:#1b4777!important
}
.content input:not([type=hidden]):not([type=checkbox]):not([type=radio]),
.content select,.content textarea,
.app-dialog input:not([type=hidden]):not([type=checkbox]):not([type=radio]),
.app-dialog select,.app-dialog textarea{
 background:#fff;color:#183b67;border:1px solid #bcd1e8;
 border-radius:10px;min-height:44px;max-width:100%;
}
.content input::placeholder,.app-dialog input::placeholder{color:#7386a0;opacity:1}
.content input:focus,.content select:focus,.content textarea:focus,
.app-dialog input:focus,.app-dialog select:focus,.app-dialog textarea:focus{
 border-color:var(--im-primary);box-shadow:0 0 0 3px rgba(31,115,204,.13)
}
.content input[type=checkbox],.content input[type=radio],.app-dialog input[type=checkbox]{
 accent-color:var(--im-primary);
}
.content .form-grid{gap:15px}
.content .form-grid>.field.full,.content .form-grid>label.full{grid-column:1/-1}
.content .table-wrap,.content .table-responsive{border:1px solid #dce8f6;border-radius:13px;overflow:auto;background:#fff}
.content .table,.content table{border-collapse:collapse}
.content .table th,.content table th{background:#eaf3ff!important;color:#184373!important;font-weight:750!important;
 font-size:11px!important;text-transform:none;white-space:nowrap}
.content .table td,.content table td{color:#234566}
.content .table tbody tr:hover,.content table tbody tr:hover{background:#f2f8ff!important}
.content .table .btn,.content table .btn{min-height:35px}
.module-tabs,.portal-tabs{overflow-x:auto;scrollbar-width:thin;border-bottom:1px solid #d5e5f4;background:#fff}
.module-tab,.portal-tabs a{white-space:nowrap;color:#345979}
.module-tab[aria-selected=true],.portal-tabs a[aria-current=page]{
 color:var(--im-primary)!important;border-color:var(--im-primary)!important;background:#eaf4ff!important
}
.app-dialog{border:1px solid #d0e0f1!important;border-radius:17px!important}
.dialog-heading{background:#f3f8ff!important;color:#123b6b}
.dialog-heading h2{color:#123b6b!important}
.dialog-footer{background:#f9fcff!important;border-top:1px solid #e0e9f3}
.content .dashboard-intro h1{color:#112f59}
.content .dashboard-action{background:#fff!important;min-height:78px}
.content .dashboard-action strong{font-size:13px;color:#153b6b}
.content .dashboard-action small{font-size:11px;color:#66809e}
.content .dashboard-action svg{color:var(--im-primary)}
/* Dashboard: quadro vivo derivado de dados reais, zero valores de exemplo. */
.im-overview{margin:20px 0 22px}
.im-overview-head{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;margin-bottom:15px}
.im-overview-head h2{font-size:20px;margin:0;color:#133c71}
.im-overview-head p{font-size:12px;color:var(--im-muted);margin:3px 0 0}
.im-overview-period{display:flex;align-items:center;gap:8px;padding:9px 12px;border:1px solid #d4e3f3;
 background:#fff;border-radius:10px;color:#254a78;font-size:12px}
.im-overview-period input{min-height:28px!important;max-width:170px}
.im-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}
.im-kpi{display:block;text-decoration:none;color:#14385f;border-radius:13px;border:1px solid #d7e7f5;
 padding:17px;min-width:0;transition:transform .15s,box-shadow .15s}
.im-kpi:hover{transform:translateY(-1px);box-shadow:0 7px 21px #153e7b15}
.im-kpi--income{background:#eaf9f0!important;border-color:#cfeada!important}
.im-kpi--pending{background:#fff7e8!important;border-color:#f0e0bd!important}
.im-kpi--events{background:#eaf4ff!important;border-color:#cfe1f7!important}
.im-kpi--people{background:#fff0f0!important;border-color:#f1d9db!important}
.im-kpi--campaign{background:#e8f4ff!important;border-color:#cee4f9!important}
.im-kpi-head{display:flex;gap:9px;align-items:center;font-size:12px;font-weight:750;color:#24476e}
.im-kpi-head svg{width:19px;height:19px;color:var(--im-primary)}
.im-kpi-value{font-size:clamp(19px,2.2vw,26px);font-weight:850;color:#0a376c;line-height:1.2;margin:13px 0 6px;overflow-wrap:anywhere}
.im-kpi-help{font-size:11px;color:#4a6c91;line-height:1.5}
.im-insights{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(260px,.7fr);gap:15px;margin-top:15px}
.im-chart,.im-action-panel{background:#fff;border:1px solid #d6e5f6;border-radius:14px;padding:18px;min-width:0}
.im-chart h3,.im-action-panel h3{font-size:15px;margin:0 0 6px}
.im-chart p,.im-action-panel p{font-size:12px;color:#67809e}
.im-chart-bars{height:172px;display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:9px;
 align-items:end;margin-top:18px;padding-top:12px;border-bottom:1px solid #cdddf0}
.im-chart-item{height:100%;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;gap:6px;min-width:0}
.im-chart-column{display:block;width:min(100%,50px);min-height:3px;height:var(--bar-height,0%);
 border-radius:6px 6px 0 0;background:linear-gradient(180deg,var(--church-secondary,#1976d2),var(--im-primary))}
.im-chart-item small{font-size:10px;color:#67809e;white-space:nowrap}
.im-actions-list{display:grid;gap:10px;margin-top:12px}
.im-actions-list a{display:flex;align-items:center;justify-content:space-between;gap:7px;
 padding:13px;border:1px solid #d9e9f8;border-radius:11px;text-decoration:none;color:#174675;
 font-size:12px;font-weight:750;background:#f7fbff}
.im-actions-list a:hover{background:#eaf4ff}
.im-actions-list span{font-size:16px;color:var(--im-primary)}
/* Fluxo financeiro: títulos, etapas, botões e status iguais nas páginas web / APK. */
body[data-app-page="finance-process.php"] .finance-gov-form h3{
 background:#e8f2ff;border-radius:8px;padding:11px 13px!important;border-bottom:0!important;
 color:#0f3d73;font-size:13px!important;margin:15px 0 10px!important
}
body[data-app-page="finance-process.php"] .finance-gov-status{font-weight:750;color:#184b80;background:#eaf3ff}
body[data-app-page="finance-process.php"] .finance-gov-section{border-top:4px solid var(--church-secondary,#1976d2)!important}
body[data-app-page="finance-process.php"] .finance-gov-form .btn{min-width:150px}
body[data-app-page="church-branding.php"] .branding-preview-brand,
body[data-app-page="contribution-settings.php"] .contribute-button{border-radius:12px}
/* Desktop: referência com sidebar fixa à esquerda, não menu horizontal herdado. */
@media(min-width:1100px){
 .sidebar{
   position:fixed!important;inset:0 auto 0 0!important;width:246px!important;height:100dvh!important;
   overflow-y:auto!important;overflow-x:hidden!important;background:#fff!important;color:#163c6a!important;
   border-right:1px solid #d7e6f8!important;box-shadow:2px 0 18px #1c426b09!important;
   z-index:61!important;display:flex!important;flex-direction:column!important;align-items:stretch!important;
 }
 .sidebar .brand{
   position:relative!important;width:auto!important;height:auto!important;min-height:86px!important;
   padding:16px 12px!important;gap:10px!important;display:flex!important;align-items:center!important;
   background:#fff!important;border-bottom:1px solid #deebf8!important;
 }
 .sidebar .brand strong{color:#143d70!important;font-size:14px!important}
 .sidebar .brand small{color:#58779a!important;display:block!important;font-size:11px!important}
 .sidebar .brand-logo{width:45px!important;height:45px!important;border:1px solid #c5d9ed!important;
   border-radius:12px!important;color:#fff!important;background:var(--im-primary)!important}
 .sidebar .current-church,.sidebar .church-switch,.sidebar>form:not(.church-switch){
   position:relative!important;inset:auto!important;top:auto!important;left:auto!important;right:auto!important;
   width:auto!important;max-width:none!important;min-height:auto!important;
 }
 .sidebar .current-church{margin:10px 10px 8px!important;padding:10px!important;background:#eaf4ff!important;
   color:#173e6b!important;border:1px solid #d2e4f7!important;height:auto!important}
 .sidebar .current-church span,.sidebar .current-church svg{color:#173e6b!important}
 .sidebar .church-switch{padding:12px!important}
 .sidebar .church-switch label{display:block!important;color:#456a91}
 .sidebar .church-switch select{background:#fff!important;color:#1a4777!important;border-color:#b9d2ef!important}
 .sidebar .nav-search{position:relative!important;inset:auto!important;right:auto!important;top:auto!important;
   display:flex!important;min-height:40px!important;margin:7px 11px!important;background:#f7fbff!important;
   color:#315a84!important;border:1px solid #d4e5f7!important}
 .sidebar .nav-search span,.sidebar .nav-search svg{color:#315a84!important}
 .sidebar .nav-search kbd{color:#456a8e!important;border-color:#b9d0e7!important}
 .sidebar .nav-list{
   display:block!important;position:relative!important;inset:auto!important;left:auto!important;top:auto!important;
   width:100%!important;height:auto!important;min-height:0!important;flex:1!important;overflow:visible!important;
   padding:8px 8px 15px!important;margin:0!important;background:#fff!important;
   border:0!important;box-shadow:none!important;color:#254b75!important
 }
 .sidebar .nav-list .nav-group{
   display:block!important;position:relative!important;margin:2px 0 3px!important;border:0!important
 }
 .sidebar .nav-list .nav-group>summary,
 .sidebar .nav-list .nav-group>summary span,
 .sidebar .nav-list .nav-group>summary svg{
   display:flex;align-items:center;position:relative!important;height:auto!important;min-height:43px!important;
   padding:0!important;background:transparent!important;color:#234d7d!important;
   text-shadow:none!important;font-size:12px!important;font-weight:700!important;opacity:1!important
 }
 .sidebar .nav-list .nav-group>summary{padding:9px 11px!important;gap:10px!important;border-radius:9px!important}
 .sidebar .nav-list .nav-group>summary:hover,.sidebar .nav-list .nav-group[open]>summary{
   background:#eaf4ff!important;color:#0b4685!important
 }
 .sidebar .nav-list .nav-group-links{
   display:block!important;position:relative!important;inset:auto!important;top:auto!important;left:auto!important;
   width:auto!important;max-height:none!important;min-width:0!important;overflow:visible!important;
   margin:2px 0 5px 16px!important;padding:0 0 0 7px!important;
   border:0!important;border-left:2px solid #dceafb!important;border-radius:0!important;
   box-shadow:none!important;background:#fff!important
 }
 .sidebar .nav-list .nav-group-links .nav-item{
   display:flex!important;position:relative!important;align-items:center!important;width:auto!important;
   margin:2px 0!important;padding:9px 10px!important;min-height:36px!important;
   color:#294d78!important;background:transparent!important;border-radius:9px!important;
   font-size:11px!important;font-weight:600!important
 }
 .sidebar .nav-list .nav-group-links .nav-item.active{
   background:var(--im-primary)!important;color:#fff!important
 }
 .sidebar .nav-list .nav-group-links .nav-item:hover:not(.active){background:#e8f3ff!important;color:#0c4380!important}
 .sidebar .sidebar-user{display:flex!important;position:relative!important;inset:auto!important;
    margin-top:auto!important;max-width:100%!important;padding:14px 12px!important;
    border-top:1px solid #dae8f7!important}
 .sidebar .sidebar-user-text strong{color:#17406f!important;max-width:125px!important}
 .sidebar .sidebar-user-text small{display:block!important;color:#6481a1!important}
 .sidebar .sidebar-user .avatar{background:#e4effd!important;color:#144c8b!important}
 .sidebar .sidebar-user a{color:#315b89!important}
 .page-wrap{margin-left:246px!important;padding-top:0!important;max-width:calc(100% - 246px)!important;width:auto!important}
 .app-topbar{position:sticky!important;top:0!important;z-index:30!important;min-height:72px!important;
   padding:13px clamp(18px,3vw,34px)!important}
 .app-topbar .menu-button{display:none!important}
 .content{max-width:1610px!important;margin:0 auto!important;padding:25px clamp(18px,3vw,36px) 42px!important}
 .app-footer{padding-left:32px!important}
 .mobile-top-brand,.im-mobile-nav{display:none!important}
}
/* Mobile and tablets: real links (not dummy tiles) + 5 accessible destinations. */
@media(max-width:1099px){
 .sidebar{background:#fff!important;color:#163e70!important;border-right:1px solid #cbdcf0!important}
 .sidebar .brand{background:#eaf4ff!important;border-bottom:1px solid #d9e8f9!important}
 .sidebar .brand strong,.sidebar .brand small{color:#164678!important}
 .sidebar .current-church{background:#eaf3ff!important;color:#1d4777!important;border-color:#d6e8fa!important}
 .sidebar .current-church svg,.sidebar .current-church span{color:#1d4777!important}
 .sidebar .nav-search{color:#244a75!important;background:#f5faff!important;border-color:#d8e8f7!important}
 .sidebar .nav-search span,.sidebar .nav-search svg{color:#244a75!important}
 .sidebar .nav-list .nav-group>summary,
 .sidebar .nav-list .nav-group>summary span,
 .sidebar .nav-list .nav-group>summary svg{
   color:#204b79!important;opacity:1!important;text-shadow:none!important
 }
 .sidebar .nav-list .nav-group-links .nav-item{color:#29547f!important;background:transparent!important}
 .sidebar .nav-list .nav-group-links .nav-item.active{background:var(--im-primary)!important;color:#fff!important}
 .sidebar .sidebar-user{border-color:#d8e5f4}
 .sidebar .sidebar-user strong,.sidebar .sidebar-user small{color:#214875!important}
 .sidebar .sidebar-user .avatar{background:#e8f4ff;color:#17477c}
 .sidebar .sidebar-close{color:#1a4775!important}
 .page-wrap{margin-left:0!important;max-width:100%!important;padding-bottom:68px!important}
 .app-topbar{position:sticky!important;top:0!important;padding:9px 15px!important;min-height:65px!important}
 .mobile-top-brand{display:flex!important;align-items:center;gap:8px;min-width:0;text-decoration:none}
 .mobile-top-brand .brand-logo{width:34px;height:34px;min-width:34px;background:var(--im-primary);
   display:grid;place-items:center;color:#fff;border:0;border-radius:10px;overflow:hidden}
 .mobile-top-brand .brand-logo img{width:100%;height:100%;object-fit:contain}
 .mobile-top-brand strong{font-size:12px;color:#143d70;max-width:130px;overflow:hidden;text-overflow:ellipsis;
    white-space:nowrap;display:block}
 .app-topbar .breadcrumb>span{display:none}
 .app-topbar .breadcrumb strong{font-size:13px!important;max-width:240px}
 .content{padding:20px 14px 26px!important}
 .im-mobile-nav{
   display:flex!important;position:fixed!important;inset:auto 0 0 0!important;z-index:91!important;
   min-height:65px;padding:7px max(8px,env(safe-area-inset-right)) calc(7px + env(safe-area-inset-bottom));
   background:#fff;border-top:1px solid #cbdff1;box-shadow:0 -5px 16px #153b6a18;
   align-items:center;justify-content:space-around;gap:4px
 }
 .im-mobile-nav a{display:flex;flex-direction:column;gap:2px;align-items:center;justify-content:center;flex:1;
   min-width:0;min-height:47px;text-decoration:none;font-size:10px;font-weight:700;
   color:#426287;border-radius:9px}
 .im-mobile-nav a svg{width:21px;height:21px;color:inherit}
 .im-mobile-nav a[aria-current=page]{background:#eaf4ff;color:var(--im-primary)}
 .im-mobile-nav a:focus-visible{outline:2px solid var(--im-primary)!important}
 .im-overview{margin-top:11px}
 .im-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}
 .im-insights{grid-template-columns:1fr}
 .im-kpi{padding:14px}
 .im-kpi-value{font-size:clamp(18px,4.2vw,24px)}
 .im-chart-bars{height:155px}
 .content .form-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
 .content .module-toolbar{flex-wrap:wrap}
}
@media(max-width:640px){
 .content .form-grid{grid-template-columns:1fr!important}
 .content .form-grid>label,.content .form-grid>.field{grid-column:1/-1}
 .im-kpis{gap:9px}
 .im-chart{padding:13px}
 .im-chart-bars{height:135px;gap:4px}
 .im-kpi-head{font-size:11px}
 .im-kpi-help{font-size:10px}
 .content .card-pad{padding:16px!important}
 .content .dashboard-intro{margin-bottom:12px}
 .app-topbar .topbar-actions .btn{font-size:11px;padding:8px;min-height:40px}
 .im-mobile-nav a{font-size:10px}
 .content .table-wrap{max-width:calc(100vw - 28px)}
 .content .finance-gov-form .btn,.content .branding-actions .btn{width:100%}
}
@media print{
 .im-mobile-nav,.mobile-top-brand{display:none!important}
 .sidebar{display:none!important}
 .page-wrap{margin:0!important;padding:0!important;max-width:none!important}
 .content{padding:0!important}
 .im-chart-column{-webkit-print-color-adjust:exact;print-color-adjust:exact}
}
@media(prefers-reduced-motion:reduce){.im-kpi{transition:none!important}}


/* Tabelas financeiras existentes reorganizadas, com contagens reais. */
.im-catalog-intro{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;
  background:#eaf4ff;border:1px solid #d5e5f7;padding:17px;border-radius:13px;margin:0 0 17px}
.im-catalog-intro strong,.im-catalog-intro small{display:block}
.im-catalog-intro strong{color:#173e70;font-size:16px}
.im-catalog-intro small{font-size:12px;color:#66809e;margin-top:5px}
.im-catalog-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px}
.im-catalog-item{display:flex;align-items:center;gap:12px;border-radius:13px;padding:17px;
   color:#173e70;text-decoration:none;background:#fff;border:1px solid #d6e5f5;
   min-width:0;box-shadow:var(--im-shadow)}
.im-catalog-item:hover{background:#f2f8ff;border-color:#9ec6eb;transform:translateY(-1px)}
.im-catalog-icon{display:grid;place-items:center;background:#e8f4ff;color:var(--im-primary);
   width:43px;height:43px;flex:0 0 43px;border-radius:11px}
.im-catalog-icon svg{width:21px;height:21px}
.im-catalog-copy{min-width:0;flex:1}
.im-catalog-copy strong,.im-catalog-copy small{display:block}
.im-catalog-copy strong{font-size:13px;line-height:1.35}
.im-catalog-copy small{font-size:11px;color:#6a809a;line-height:1.4;margin-top:5px}
.im-catalog-count{font-size:11px;font-weight:700;color:#1a6a3b;background:#e4f6e8;
   padding:6px 8px;border-radius:100px;white-space:nowrap}
.im-catalog-arrow{font-size:24px;color:var(--im-primary)}
.im-catalog-foot{margin-top:22px}
.im-catalog-foot p{font-size:13px;color:#567394;line-height:1.6}
@media(max-width:700px){
 .im-catalog-grid{grid-template-columns:1fr}
 .im-catalog-item{padding:12px}
 .im-catalog-count{font-size:10px}
}

/* Entrada real do Igreja Master — v3.7.29 */
body.im-login-page{margin:0;min-height:100dvh;display:grid;place-items:center;
  background:radial-gradient(circle at 88% 5%,#d6eaff 0,transparent 30%),#f2f7fd;
  color:#163d6a;font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif;}
.im-login-layout{width:min(950px,calc(100% - 32px));display:grid;grid-template-columns:1fr 1fr;
  border:1px solid #d4e4f6;border-radius:24px;overflow:hidden;
  background:#fff;box-shadow:0 18px 60px rgba(8,47,102,.12);}
.im-login-about{display:flex;flex-direction:column;justify-content:center;
  color:white;background:linear-gradient(155deg,#092e6c,#125ba9 72%,#187ac7);
  padding:clamp(24px,4vw,48px);min-height:475px;}
.im-login-symbol{display:grid;place-items:center;width:72px;height:72px;border-radius:18px;
  color:#0d4e9c;background:#fff;font-weight:900;font-size:42px;
  box-shadow:0 8px 30px #061c3a38}
.im-login-about h1{color:#fff;font-weight:820;font-size:clamp(27px,3vw,36px);line-height:1.18;
  margin:30px 0 10px}
.im-login-about p{color:#d9eaff;font-size:14px;line-height:1.7;max-width:290px}
.im-login-feature{color:#e7f3ff;font-size:12px;line-height:1.55;margin-top:25px;
  padding:13px 14px;background:#ffffff13;border:1px solid #ffffff26;border-radius:12px}
.im-login-card{display:flex;flex-direction:column;justify-content:center;
  padding:clamp(24px,4vw,48px);background:#fff;}
.im-login-card h2{font-size:24px;color:#11376c;margin:0 0 6px;letter-spacing:-.03em}
.im-login-card>p{color:#647d9b;font-size:13px;line-height:1.6;margin:0 0 25px}
.im-login-card .field{display:grid;gap:7px;margin-bottom:16px}
.im-login-card .field label{font-weight:700;font-size:12px;color:#184271}
.im-login-card .field input{min-height:48px;width:100%;border:1px solid #b9d3ec;
  background:#fff;color:#14375b;font-size:15px;padding:12px;border-radius:10px}
.im-login-card .field input:focus{outline:3px solid #d2eaff;border-color:#0d55a1}
.im-login-card .im-password-wrap{display:flex;align-items:center;gap:7px}
.im-login-card .im-password-wrap input{min-width:0;flex:1}
.im-login-card .im-password-toggle{border:1px solid #c8dcf1;background:#edf6ff;color:#134577;
  padding:10px;border-radius:9px;min-height:48px;min-width:65px;cursor:pointer;font-size:12px}
.im-login-card button[type=submit]{width:100%;min-height:50px;
  border-radius:10px;background:#0d47a1;color:white;font-size:14px;font-weight:750;
  margin-top:4px;border:0;cursor:pointer}
.im-login-card button[type=submit]:hover{background:#09377e}
.im-login-note{font-size:11px;color:#7990ac;line-height:1.6;margin-top:22px}
.im-login-card .alert-error{color:#9b2d3c;border:1px solid #f0c8cf;background:#fff2f4;
  padding:12px;border-radius:9px;font-size:12px;margin-bottom:17px}
@media(max-width:760px){
 .im-login-layout{grid-template-columns:1fr;width:min(460px,calc(100% - 20px));margin:10px auto}
 .im-login-about{min-height:auto;padding:23px;gap:4px}
 .im-login-symbol{width:50px;height:50px;border-radius:13px;font-size:30px}
 .im-login-about h1{font-size:23px;margin:12px 0 3px}
 .im-login-about p{font-size:12px;margin:0}
 .im-login-feature{display:none}
 .im-login-card{padding:25px 22px}
}
